def minimax_nim(n, maximise):
    # Cas de base : il ne reste plus d'allumette à prendre. Le joueur dont
    # c'est le tour ne peut donc pas jouer : c'est l'ADVERSAIRE qui vient de
    # prendre la dernière allumette au coup précédent, et qui a donc gagné.
    if n == 0:
        # Si c'est le tour de A (maximise) mais qu'il ne peut pas jouer,
        # c'est B qui a gagné : la valeur (du point de vue de A) est -1.
        # Si c'est le tour de B, c'est A qui a gagné : la valeur est +1.
        return -1 if maximise else 1

    if maximise:
        # Le joueur A cherche à MAXIMISER la valeur : on essaie chaque coup
        # possible (retirer 1, 2 ou 3 allumettes, sans dépasser n), et on
        # garde la meilleure valeur trouvée parmi tous les coups
        meilleure_valeur = -2  # plus petit que toute valeur possible (-1 au minimum)
        for coup in (1, 2, 3):
            if coup <= n:
                # Après ce coup, c'est au tour de B (maximise devient False)
                valeur = minimax_nim(n - coup, False)
                if valeur > meilleure_valeur:
                    meilleure_valeur = valeur
        return meilleure_valeur
    else:
        # Le joueur B cherche à MINIMISER la valeur (du point de vue de A) :
        # on garde cette fois la PIRE valeur trouvée parmi tous les coups
        pire_valeur = 2  # plus grand que toute valeur possible (1 au maximum)
        for coup in (1, 2, 3):
            if coup <= n:
                # Après ce coup, c'est au tour de A (maximise devient True)
                valeur = minimax_nim(n - coup, True)
                if valeur < pire_valeur:
                    pire_valeur = valeur
        return pire_valeur

