VALEUR_DEFAITE = -10


def evaluation_nim(n):
    return 1 if n % 2 == 1 else -1


def meilleur_coup_negamax_profondeur(n, profondeur):
    # Négamax, avec les deux mêmes cas de base que pour le minimax de
    # l'exercice précédent : la vraie fin de partie (n == 0) et l'arrêt
    # anticipé faute de profondeur (estimation)
    def score(n, profondeur):
        if n == 0:
            # Fin de partie réelle : le joueur au trait ne peut pas jouer,
            # il a donc perdu — valeur exacte
            return VALEUR_DEFAITE
        if profondeur == 0:
            # On s'arrête là : evaluation_nim(n) est déjà exprimée du point
            # de vue du joueur au trait, exactement la convention du
            # négamax — pas besoin de l'adapter, contrairement au minimax
            return evaluation_nim(n)
        meilleure_valeur = float('-inf')
        for coup in (1, 2, 3):
            if coup <= n:
                # Après ce coup, c'est au tour de l'adversaire : sa valeur
                # est l'opposée de la nôtre
                valeur = -score(n - coup, profondeur - 1)
                if valeur > meilleure_valeur:
                    meilleure_valeur = valeur
        return meilleure_valeur

    meilleur_coup = None
    meilleure_valeur = float('-inf')
    for coup in (1, 2, 3):
        if coup <= n:
            valeur = -score(n - coup, profondeur - 1)
            if valeur > meilleure_valeur:
                meilleure_valeur = valeur
                meilleur_coup = coup
    return meilleur_coup
